package com.daniil.wristlens.core;
import java.io.*;import org.junit.Test;import static org.junit.Assert.*;
public class AudioPacketTest {
 private byte[] encode(short[] pcm)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();AudioPacket.write(new DataOutputStream(b),17,pcm);return b.toByteArray();}
 @Test public void independentlyDecodableAndSmallEnoughForPreview()throws Exception{short[] input=new short[1280];for(int i=0;i<input.length;i++)input[i]=(short)(12000*Math.sin(2*Math.PI*400*i/16000));byte[] b=encode(input);assertTrue(b.length<680);var f=AudioPacket.read(new DataInputStream(new ByteArrayInputStream(b)));assertEquals(17,f.sequence());double signal=0,error=0;for(int i=0;i<input.length;i++){signal+=(double)input[i]*input[i];double d=input[i]-f.pcm()[i];error+=d*d;}assertTrue(10*Math.log10(signal/error)>18);}
 @Test public void allFrameBoundariesConsumeExactlyOnePacket()throws Exception{for(int n:new int[]{1,2,3,1279,1280}){byte[] b=encode(new short[n]);ByteArrayOutputStream joined=new ByteArrayOutputStream();joined.write(b);joined.write(b);DataInputStream in=new DataInputStream(new ByteArrayInputStream(joined.toByteArray()));assertEquals(n,AudioPacket.read(in).pcm().length);assertEquals(n,AudioPacket.read(in).pcm().length);assertEquals(0,in.available());}}
 @Test public void invalidSizesAndTruncatedPacketsFail()throws Exception{assertThrows(IOException.class,()->encode(new short[0]));assertThrows(IOException.class,()->encode(new short[1281]));byte[] b=encode(new short[50]);assertThrows(IOException.class,()->AudioPacket.read(new DataInputStream(new ByteArrayInputStream(java.util.Arrays.copyOf(b,b.length-1)))));}
 @Test public void malformedHeadersAreRejectedBeforeAllocation()throws Exception{byte[] b=encode(new short[20]);b[0]=0;assertThrows(IOException.class,()->AudioPacket.read(new DataInputStream(new ByteArrayInputStream(b))));byte[] a=encode(new short[20]);a[16]=(byte)255;assertThrows(IOException.class,()->AudioPacket.read(new DataInputStream(new ByteArrayInputStream(a))));}
}
